package com.rezoxnemesis.videostudio;

import ai.onnxruntime.*;
import ai.onnxruntime.platform.Fp16Conversions;
import android.graphics.*;
import org.json.JSONObject;
import java.io.*;
import java.nio.*;
import java.util.*;
import java.util.concurrent.TimeUnit;

/** Optional16-token Plus/PlusFace appearance attention and structural residual provider. Native CPU only. */
final class LocalDrawingPlusEngine implements AutoCloseable {
 private static final long[][] SHAPES={{1,320,64,64},{1,320,64,64},{1,320,64,64},{1,320,32,32},{1,640,32,32},{1,640,32,32},{1,640,16,16},{1,1280,16,16},{1,1280,16,16},{1,1280,8,8},{1,1280,8,8},{1,1280,8,8},{1,1280,8,8}};
 private static final int[] INNER={320,320,640,640,1280,1280,1280,1280,1280,640,640,640,320,320,320,1280};
 private static final int KV_COUNT=kvCount();
 private static int kvCount(){int n=0;for(int inner:INNER)n+=inner*16*2;return n;}
 private final LocalDrawingEngine runner=new LocalDrawingEngine();private final OrtEnvironment environment=OrtEnvironment.getEnvironment();private int unetPasses,controlPasses;private long elapsedMs;private int attemptedSteps;
 String runtimeVersion(){return runner.runtimeVersion();}
 JSONObject performance()throws Exception{return new JSONObject().put("elapsedMs",elapsedMs).put("unetPassesThisAttempt",unetPasses).put("controlNetPassesThisAttempt",controlPasses).put("denoisingStepsThisAttempt",attemptedSteps).put("maxUnetPassesPerStep",2).put("maxControlNetPassesPerStep",2).put("appearanceStrengthSemantics","Scale all16 per-layer actual image-attention V tensors; unconditional comes from CLIP of zero normalized pixels through the selected head").put("structureStrengthSemantics","All13 actual output residuals multiplied by explicit strength");}
 Bitmap render(File model,Bitmap primary,Bitmap appearance,Bitmap structure,JSONObject settings,JSONObject conditioning,File checkpoints,String identity,LocalDrawingEngine.Progress progress)throws Exception {
  LocalDrawingEngine.validate(settings);SketchDocument.fields(conditioning,"appearanceStrength,structureStrength,adapter,structureEdges");if(conditioning.has("structureEdges"))LocalDrawingPairedSource.validateEdges(conditioning.getJSONObject("structureEdges"));String adapter=conditioning.getString("adapter");if(!adapter.equals("plus_face")&&!adapter.equals("plus"))throw SketchDocument.bad("Explicit Plus adapter required");double appearanceStrength=SketchDocument.number(conditioning,"appearanceStrength",0,1),structureStrength=SketchDocument.number(conditioning,"structureStrength",0,1);
  if(primary.getWidth()!=512||primary.getHeight()!=512||appearance.getWidth()!=224||appearance.getHeight()!=224||structure.getWidth()!=512||structure.getHeight()!=512||!identity.matches("[a-f0-9]{64}"))throw new IllegalArgumentException("Exact bounded paired inputs and request identity required");if(!checkpoints.isDirectory()&&!checkpoints.mkdirs())throw new IOException("Cannot create paired checkpoints");boolean acquired=false;long start=System.currentTimeMillis();
  try {
   while(!LocalDrawingEngine.INFERENCE_SLOT.tryAcquire(100,TimeUnit.MILLISECONDS))LocalDrawingEngine.check();acquired=true;LocalDrawingEngine.check();LocalDrawingTokenizer tokenizer=new LocalDrawingTokenizer(model);LocalDrawingSchedule schedule=new LocalDrawingSchedule();int[] times=schedule.timesteps(settings.getInt("steps"),settings.getDouble("strength"));
   float[] text=LocalDrawingEngine.read(checkpoints,"conditioning.bin",identity,LocalDrawingEngine.EMBEDDING*2).values;
   if(text==null){progress.report(5,"Encoding positive/negative prompts locally");try(OrtSession session=runner.open(model,"text_encoder/model.onnx")){float[] negative=runner.encode(session,tokenizer.encode(settings.optString("negativePrompt",""))),positive=runner.encode(session,tokenizer.encode(settings.getString("prompt")));text=new float[LocalDrawingEngine.EMBEDDING*2];System.arraycopy(negative,0,text,0,negative.length);System.arraycopy(positive,0,text,negative.length,positive.length);}LocalDrawingEngine.save(checkpoints,"conditioning.bin",identity,0,text);}
   float[] image=LocalDrawingEngine.read(checkpoints,"plus-attention-conditioning.bin",identity,KV_COUNT*2).values;
   if(image==null){progress.report(9,"Encoding selected appearance into native16-token attention");float[][] hidden=new float[2][];
    try(OrtSession session=runner.open(model,"image_encoder/model.onnx")){for(int branch=0;branch<2;branch++){LocalDrawingEngine.check();float[] rgb=branch==0?new float[3*224*224]:LocalDrawingPairedSource.clipTensor(appearance);try(OnnxTensor pixels=half(rgb,1,3,224,224);OrtSession.Result result=runner.run(session,Collections.singletonMap("pixel_values",pixels))){hidden[branch]=halfValues(result,"penultimate_hidden_states",1,257,1280);}}}
    image=new float[KV_COUNT*2];try(OrtSession session=runner.open(model,adapter.equals("plus_face")?"ip_adapter/face.onnx":"ip_adapter/plus.onnx")){for(int branch=0;branch<2;branch++){LocalDrawingEngine.check();try(OnnxTensor input=runner.tensor(hidden[branch],1,257,1280);OrtSession.Result result=runner.run(session,Collections.singletonMap("hidden",input))){int offset=branch*KV_COUNT;for(int layer=0;layer<16;layer++){float[] key=fullValues(result,"ipk_"+layer,1,INNER[layer],16),value=fullValues(result,"ipv_"+layer,1,16,INNER[layer]);System.arraycopy(key,0,image,offset,key.length);offset+=key.length;System.arraycopy(value,0,image,offset,value.length);offset+=value.length;}}}}
    LocalDrawingEngine.save(checkpoints,"plus-attention-conditioning.bin",identity,0,image);
   }
   LocalDrawingEngine.Snapshot resumed=LocalDrawingEngine.read(checkpoints,"denoising.bin",identity,LocalDrawingEngine.LATENTS);float[] latents=resumed.values;int completed=resumed.step;if(completed<0||completed>times.length)throw new IOException("LOCAL_DRAWING_CHECKPOINT_INVALID");
   if(latents==null){float[] clean=LocalDrawingEngine.read(checkpoints,"encoded.bin",identity,LocalDrawingEngine.LATENTS).values;if(clean==null){progress.report(12,"Encoding the authored frame as the initial image");int[] pixels=new int[512*512];primary.getPixels(pixels,0,512,0,0,512,512);float[] rgb=new float[3*pixels.length];for(int y=0;y<512;y++){LocalDrawingEngine.check();for(int x=0;x<512;x++){int i=y*512+x;colorChannels(rgb,pixels.length,i,pixels[i]);}}
     try(OrtSession session=runner.open(model,"vae_encoder/model.onnx");OnnxTensor input=runner.tensor(rgb,1,3,512,512);OrtSession.Result result=runner.run(session,Collections.singletonMap("sample",input))){clean=LocalDrawingEngine.floats(result,0,1,4,64,64);}for(int i=0;i<clean.length;i++)clean[i]*=LocalDrawingSchedule.LATENT_SCALE;LocalDrawingEngine.save(checkpoints,"encoded.bin",identity,0,clean);}
    Random random=new Random(settings.getLong("seed"));float[] noise=new float[LocalDrawingEngine.LATENTS];for(int i=0;i<noise.length;i++)noise[i]=(float)random.nextGaussian();latents=schedule.addNoise(clean,noise,times[0]);completed=0;LocalDrawingEngine.save(checkpoints,"denoising.bin",identity,0,latents);
   }
   if(completed<times.length){int[] pixels=new int[512*512];structure.getPixels(pixels,0,512,0,0,512,512);float[] edges=new float[3*pixels.length];for(int i=0;i<pixels.length;i++){if(i%512==0)LocalDrawingEngine.check();if(pixels[i]!=Color.WHITE&&pixels[i]!=Color.BLACK)throw new IOException("Frozen structural guide must be binary opaque pixels");float value=pixels[i]==Color.WHITE?1:0;edges[i]=value;edges[pixels.length+i]=value;edges[2*pixels.length+i]=value;}
    progress.report(18,"Loading optional appearance and structural networks");try(OrtSession control=structureStrength>0?runner.open(model,"controlnet/model.onnx"):null;OrtSession unet=runner.open(model,"unet/model.onnx");OnnxTensor negative=half(Arrays.copyOfRange(text,0,LocalDrawingEngine.EMBEDDING),1,77,768);OnnxTensor positive=half(Arrays.copyOfRange(text,LocalDrawingEngine.EMBEDDING,2*LocalDrawingEngine.EMBEDDING),1,77,768);OnnxTensor guide=half(edges,1,3,512,512)){
     for(int step=completed;step<times.length;step++){LocalDrawingEngine.check();progress.report(20+60*step/times.length,"Paired local drawing: step "+(step+1)+" of "+times.length);float[][] negativeResidual=residuals(control,latents,times[step],negative,guide,structureStrength);float[] a=predict(unet,latents,times[step],negative,image,0,appearanceStrength,negativeResidual);float[][] positiveResidual=residuals(control,latents,times[step],positive,guide,structureStrength);float[] b=predict(unet,latents,times[step],positive,image,1,appearanceStrength,positiveResidual);

      double guidance=settings.getDouble("guidance");for(int i=0;i<a.length;i++)a[i]=(float)(a[i]+guidance*(b[i]-a[i]));latents=schedule.step(latents,a,times[step],step+1<times.length?times[step+1]:-1);attemptedSteps++;LocalDrawingEngine.save(checkpoints,"denoising.bin",identity,step+1,latents);elapsedMs=System.currentTimeMillis()-start;OpenPipelineArtifacts.writeAtomic(new File(checkpoints,"paired-performance.json"),performance().toString().getBytes(java.nio.charset.StandardCharsets.UTF_8),64*1024);
     }
    }
   }
   LocalDrawingEngine.check();progress.report(85,"Decoding paired model output locally");for(int i=0;i<latents.length;i++)latents[i]/=LocalDrawingSchedule.LATENT_SCALE;float[] rgb;try(OrtSession session=runner.open(model,"vae_decoder/model.onnx");OnnxTensor input=runner.tensor(latents,1,4,64,64);OrtSession.Result result=runner.run(session,Collections.singletonMap("latent_sample",input))){rgb=LocalDrawingEngine.floats(result,0,1,3,512,512);}int[] pixels=new int[512*512];for(int y=0;y<512;y++){LocalDrawingEngine.check();for(int x=0;x<512;x++){int i=y*512+x;pixels[i]=Color.rgb(LocalDrawingEngine.channel(rgb[i]),LocalDrawingEngine.channel(rgb[pixels.length+i]),LocalDrawingEngine.channel(rgb[2*pixels.length+i]));}}LocalDrawingEngine.check();Bitmap output=Bitmap.createBitmap(512,512,Bitmap.Config.ARGB_8888);output.setPixels(pixels,0,512,0,0,512,512);elapsedMs=System.currentTimeMillis()-start;return output;
  }finally{elapsedMs=System.currentTimeMillis()-start;if(acquired)LocalDrawingEngine.INFERENCE_SLOT.release();}
 }
 private static void colorChannels(float[] rgb,int count,int i,int color){rgb[i]=Color.red(color)/127.5f-1;rgb[count+i]=Color.green(color)/127.5f-1;rgb[2*count+i]=Color.blue(color)/127.5f-1;}
 private OnnxTensor half(float[] values,long...shape)throws Exception{return OnnxTensor.createTensor(environment,Fp16Conversions.convertFloatBufferToFp16Buffer(FloatBuffer.wrap(values)),shape,OnnxJavaType.FLOAT16);}
 private static String residualName(int i){return i<12?"down_residual_"+i:"mid_residual";}
 private float[][] residuals(OrtSession control,float[] latents,int time,OnnxTensor text,OnnxTensor guide,double strength)throws Exception {float[][] values=new float[13][];if(control==null){for(int i=0;i<13;i++){int count=1;for(long dimension:SHAPES[i])count*=dimension;values[i]=new float[count];}return values;}
  try(OnnxTensor sample=half(latents,1,4,64,64);OnnxTensor timestep=half(new float[]{time},1)){Map<String,OnnxTensor> inputs=new LinkedHashMap<>();inputs.put("sample",sample);inputs.put("timestep",timestep);inputs.put("encoder_hidden_states",text);inputs.put("canny_image",guide);try(OrtSession.Result result=runner.run(control,inputs)){controlPasses++;for(int i=0;i<13;i++){values[i]=halfValues(result,residualName(i),SHAPES[i]);for(int j=0;j<values[i].length;j++)values[i][j]*=strength;}}}return values;
 }
 private float[] predict(OrtSession unet,float[] latents,int time,OnnxTensor text,float[] image,int branch,double strength,float[][] residuals)throws Exception {Map<String,OnnxTensor> inputs=new LinkedHashMap<>();List<OnnxTensor> owned=new ArrayList<>();try{OnnxTensor sample=half(latents,1,4,64,64),timestep=half(new float[]{time},1);owned.add(sample);owned.add(timestep);inputs.put("sample",sample);inputs.put("timestep",timestep);inputs.put("encoder_hidden_states",text);int offset=branch*KV_COUNT;for(int layer=0;layer<16;layer++){int count=INNER[layer]*16;float[] key=Arrays.copyOfRange(image,offset,offset+count);offset+=count;float[] value=Arrays.copyOfRange(image,offset,offset+count);offset+=count;for(int k=0;k<value.length;k++)value[k]*=strength;OnnxTensor k=half(key,1,INNER[layer],16),v=half(value,1,16,INNER[layer]);owned.add(k);owned.add(v);inputs.put("ipk_"+layer,k);inputs.put("ipv_"+layer,v);}for(int i=0;i<13;i++){OnnxTensor tensor=half(residuals[i],SHAPES[i]);owned.add(tensor);inputs.put(residualName(i),tensor);}try(OrtSession.Result result=runner.run(unet,inputs)){unetPasses++;return halfValues(result,"noise_pred",1,4,64,64);}}finally{for(OnnxTensor tensor:owned)tensor.close();}}
 private static float[] halfValues(OrtSession.Result result,String name,long...shape)throws Exception {OnnxValue value=result.get(name).orElseThrow(()->new IllegalStateException("Missing paired model output "+name));if(!(value instanceof OnnxTensor))throw new IOException("Paired output must be tensor");OnnxTensor tensor=(OnnxTensor)value;if(tensor.getInfo().type!=OnnxJavaType.FLOAT16||!Arrays.equals(shape,tensor.getInfo().getShape()))throw new IOException("PAIRED_TENSOR_CONTRACT_DIFFERS: "+name);FloatBuffer data=tensor.getFloatBuffer();float[] values=new float[data.remaining()];data.get(values);for(float number:values)if(!Float.isFinite(number))throw new IOException("Non-finite paired model output: "+name);return values;}
 private static float[] fullValues(OrtSession.Result result,String name,long...shape)throws Exception {OnnxValue value=result.get(name).orElseThrow(()->new IllegalStateException("Missing Plus output "+name));if(!(value instanceof OnnxTensor))throw new IOException("Plus output must be tensor");OnnxTensor tensor=(OnnxTensor)value;if(tensor.getInfo().type!=OnnxJavaType.FLOAT||!Arrays.equals(shape,tensor.getInfo().getShape()))throw new IOException("PLUS_TENSOR_CONTRACT_DIFFERS: "+name);FloatBuffer buffer=tensor.getFloatBuffer();float[] output=new float[buffer.remaining()];buffer.get(output);for(float n:output)if(!Float.isFinite(n))throw new IOException("Nonfinite Plus tensor "+name);return output;}
 @Override public void close(){runner.close();}
}
